#!/usr/bin/env python3
"""Seed reviewable decision-support content; links are official NFL/source publishers."""
import csv
from pathlib import Path
D=Path(__file__).resolve().parent/'data'; D.mkdir(exist_ok=True)

def write(name,rows):
    with (D/name).open('w',newline='',encoding='utf-8') as f:
        w=csv.DictWriter(f,fieldnames=list(rows[0]),lineterminator="\n");w.writeheader();w.writerows(rows)

